function validProduct(p){return p&&Number.isFinite(p.id)&&p.name&&p.category&&Number.isFinite(p.price)&&Number.isFinite(p.originalPrice)&&p.image&&p.description&&p.brand&&Number.isFinite(p.rating)&&Number.isFinite(p.reviewCount)&&Number.isFinite(p.stock)&&Number.isFinite(p.discount)}
let state;try{state=JSON.parse(localStorage.getItem('billcart')||'{"cart":[],"wish":[],"orders":[],"user":null,"coupon":"","dark":false}')}catch{state={cart:[],wish:[],orders:[],user:null,coupon:'',dark:false}};state.users=state.users||{};state.coupons=state.coupons||{WELCOME10:{type:'percent',value:10,max:500},SAVE20:{type:'percent',value:20,min:2000,max:1000},BILL50:{type:'fixed',value:50,min:1000},FREESHIP:{type:'shipping',value:0}};state.addresses=state.addresses||[];state.profiles=state.profiles||{};if(Array.isArray(state.catalogue)){state.catalogue.forEach(saved=>{let existing=products.find(p=>p.id===saved.id);if(existing)Object.assign(existing,saved);else products.push(saved)})}
state.cart=Array.isArray(state.cart)?state.cart.filter(x=>products.some(p=>p.id===x.id)).map(x=>({id:Number(x.id),q:Math.max(1,Number(x.q)||1)})):[];state.wish=Array.isArray(state.wish)?state.wish:[];state.orders=Array.isArray(state.orders)?state.orders.map(o=>({...o,paymentMethod:o.paymentMethod||o.payment||'Cash on Delivery',paymentStatus:o.paymentStatus||((o.paymentMethod||o.payment)==='Cash on Delivery'?'Pending':'Paid'),orderStatus:o.orderStatus||o.status||'Confirmed'})):[]; if(state.dark)document.body.classList.add('dark');
const save=()=>{if(state.user)state.users[state.user.id]={...(state.users[state.user.id]||{}),cart:state.cart,wish:state.wish,addresses:state.addresses,profile:state.profiles[state.user.id]||{}};state.catalogue=products;try{localStorage.setItem('billcart',JSON.stringify(state))}catch(e){console.error(e);toast('Storage is full; changes may not persist.')}};function switchUser(user){state.user=user;const saved=state.users[user.id]||{};state.cart=saved.cart||[];state.wish=saved.wish||[];state.addresses=saved.addresses||[];state.coupon='';state.checkout={paymentMethod:'UPI'};} const money=n=>'₹'+Math.round(Number.isFinite(Number(n))?Number(n):0).toLocaleString('en-IN');
function bill(){let sub=state.cart.reduce((a,x)=>a+(products.find(p=>p.id==x.id)?.p||0)*x.q,0),productDiscount=state.cart.reduce((a,x)=>{let p=products.find(p=>p.id==x.id);return a+(p?Math.max(0,p.old-p.p)*x.q:0)},0),coupon=0,delivery=sub>=999?0:sub?79:0,rule=state.coupons[state.coupon];if(rule){if(rule.min&&sub<rule.min)rule=null;else if(rule.type==='percent')coupon=Math.min(sub*rule.value/100,rule.max||Infinity);else if(rule.type==='fixed')coupon=Math.min(sub,rule.value);else if(rule.type==='shipping')delivery=0}let taxable=Math.max(0,sub-coupon),taxRate=state.cart.reduce((a,x)=>{let p=products.find(p=>p.id==x.id);return a+(p?p.gstRate*x.q*p.p:0)},0)/Math.max(1,sub),gst=taxable*taxRate/100;return{sub,productDiscount,coupon,taxable,cgst:gst/2,sgst:gst/2,delivery,total:taxable+gst+delivery}}
function toast(t){let e=document.querySelector('.toast');e.textContent=t;e.classList.remove('hidden');setTimeout(()=>e.classList.add('hidden'),2400)}
function nav(){let destination=state.user?.role==='admin'?'admin':state.user?'dashboard':'login';let account=state.user?`<button onclick="go('${destination}')">◉ ${state.user.name.split(' ')[0]}</button><button title="Logout" onclick="logout()">Logout</button>`:`<button onclick="go('login')">Login</button>`;return `<nav class="nav"><div class="wrap"><button class="logo" onclick="go('home')"><b>✓</b>BillCart</button><div class="navlinks"><button onclick="go('home')">Home</button><button onclick="go('shop')">Shop</button><button onclick="go('orders')">Orders</button></div><div class="search"><input id="search" oninput="search(this.value)" placeholder="Search products, brands, categories…"></div><div class="icons"><button onclick="go('wishlist')">♡ <span class="badge">${state.wish.length}</span></button><button onclick="go('cart')">Cart <span class="badge">${state.cart.reduce((a,x)=>a+x.q,0)}</span></button><button onclick="toggleTheme()">${state.dark?'☀':'◐'}</button>${account}</div></div></nav>`}
function productCard(p){if(!validProduct(p))return '';let wished=state.wish.includes(p.id);return `<article class="card"><button class="wish ${wished?'active':''}" onclick="wish(${p.id})">${wished?'♥':'♡'}</button><button class="product-img" onclick="go('product',${p.id})" aria-label="View ${p.n}"><img src="${p.image}" alt="${p.n}" loading="lazy" onerror="this.onerror=null;this.src=productFallback(products.find(x=>x.id===${p.id}))">${p.icon}</button><div class="card-body"><div class="brand">${p.b}</div><div class="name">${p.n}</div><div class="rating">★ ${p.r} <span class="muted">(${p.reviewCount})</span></div><div class="price">${money(p.p)} <span class="old">${money(p.old)}</span></div><div class="card-foot"><span class="stock">${p.stock?'In stock':'Out of stock'}</span><button class="btn" ${p.stock?'':'disabled'} onclick="add(${p.id})">${p.stock?'Add':'Sold out'}</button></div></div></article>`}
function home(){return `${nav()}<section class="hero"><div class="wrap hero-grid"><div><div class="eyebrow">Smart commerce, simplified</div><h1>Everything You Need.<br>One Smart Cart.</h1><p class="muted">Shop your favorite products, enjoy a smooth checkout, and receive a professional digital invoice instantly.</p><div class="hero-actions"><button class="btn" onclick="go('shop')">Shop Now</button><button class="btn secondary" onclick="go('shop')">Explore Categories</button></div></div><div class="hero-art"><div class="brand">BILLCART DIGITAL INVOICE</div><div class="mini-product"><div class="fakeimg">🎧</div><div><b>Aero Wireless Headphones</b><br><span class="muted">GST-ready · Fast delivery</span></div><b>${money(2499)}</b></div><div class="invoice-mini">✓ Payment protected <span style="float:right">▦ QR invoice</span></div></div></div></section><main class="wrap"><section class="section"><div class="section-head"><h2>Shop by category</h2><button class="link" onclick="go('shop')">View all →</button></div><div class="category-grid">${categories.map(([c,i])=>`<button class="category" onclick="go('shop','${c}')"><i>${i}</i><b>${c}</b><small>${products.filter(p=>p.c===c).length||'12'} products</small></button>`).join('')}</div></section><section class="section"><div class="section-head"><div><div class="eyebrow">Popular right now</div><h2>Featured products</h2></div><button class="link" onclick="go('shop')">Shop all →</button></div><div class="grid">${products.slice(0,8).map(productCard).join('')}</div></section><section class="panel"><div class="eyebrow">Smart Recommendations</div><h2>Because you viewed Electronics</h2><p class="muted">Rule-based suggestions from your browsing and cart activity.</p><div class="grid">${products.filter(p=>p.c==='Electronics').slice(0,4).map(productCard).join('')}</div></section></main>${assistant()}${footer()}<div class="toast hidden"></div>`}
let shopFilters={category:'',max:100000,stock:false,sort:'Popular',query:''};function renderShopGrid(){let grid=document.querySelector('#shopgrid');if(!grid)return;let a=products.filter(p=>(!shopFilters.category||p.c===shopFilters.category)&&p.p<=shopFilters.max&&(!shopFilters.stock||p.stock>0)&&(!shopFilters.query||`${p.n} ${p.b} ${p.c}`.toLowerCase().includes(shopFilters.query.toLowerCase())));if(shopFilters.sort.includes('low'))a.sort((x,y)=>x.p-y.p);if(shopFilters.sort.includes('high'))a.sort((x,y)=>y.p-x.p);if(shopFilters.sort.includes('rated'))a.sort((x,y)=>y.r-x.r);grid.innerHTML=a.map(productCard).join('')||'<p class="muted">No products match these filters.</p>';let count=document.querySelector('#resultCount');if(count)count.textContent=a.length+' products'}function shop(category=''){shopFilters={category:category||'',max:100000,stock:false,sort:'Popular',query:''};return `${nav()}<main class="wrap"><div class="section-head"><div><div class="eyebrow">Curated catalogue</div><h2>Shop products</h2></div><span class="muted" id="resultCount">${products.length} products</span></div><div class="shop-layout"><aside class="panel filters"><b>Filters</b><label>Category<select onchange="shopFilters.category=this.value;renderShopGrid()"><option value="">All categories</option>${categories.map(x=>`<option value="${x[0]}" ${x[0]===category?'selected':''}>${x[0]}</option>`).join('')}</select></label><label>Maximum price <output id="priceValue">₹100000</output><input class="range" type="range" min="100" max="100000" value="100000" oninput="shopFilters.max=Number(this.value);document.querySelector('#priceValue').textContent=money(this.value);renderShopGrid()"></label><label><input type="checkbox" onchange="shopFilters.stock=this.checked;renderShopGrid()"> In stock only</label><label>Sort<select onchange="shopFilters.sort=this.value;renderShopGrid()"><option>Popular</option><option>Price low to high</option><option>Price high to low</option><option>Highest rated</option></select></label></aside><div class="grid" id="shopgrid">${products.filter(p=>!category||p.c===category).map(productCard).join('')}</div></div></main><div class="toast hidden"></div>`}function cart(){let b=bill();let threshold=Math.max(0,999-b.sub);return `${nav()}<main class="wrap"><div class="section-head"><div><div class="eyebrow">Your smart cart</div><h2>Cart & billing</h2></div><button class="link" onclick="go('shop')">← Continue shopping</button></div>${!state.cart.length?`<div class="panel empty"><h2>Your cart is waiting for something good.</h2><button class="btn" onclick="go('shop')">Start Shopping</button></div>`:`<div class="cart-layout"><section class="panel">${state.cart.map(x=>{let p=products.find(p=>p.id==x.id);return `<div class="cart-item"><div class="fakeimg">${p.icon}</div><div style="flex:1"><b>${p.n}</b><div class="muted">${p.b} · GST ${18}%</div><b>${money(p.p)}</b></div><div class="qty"><button onclick="qty(${p.id},-1)">−</button><span>${x.q}</span><button onclick="qty(${p.id},1)">+</button></div><button class="link" onclick="remove(${p.id})">Remove</button></div>`}).join('')}</section><aside class="panel summary"><b>Billing summary</b><div class="coupon"><input id="coupon" placeholder="Coupon code" value="${state.coupon}"><button class="btn" onclick="applyCoupon()">Apply</button></div>${b.sub<999?`<div class="muted">Add ${money(threshold)} more to get FREE DELIVERY</div><div class="progress"><b style="width:${Math.min(100,b.sub/999*100)}%"></b></div>`:`<div class="up">🎉 You unlocked FREE DELIVERY</div>`}<div class="line"><span>Subtotal</span><span>${money(b.sub)}</span></div><div class="line"><span>Product savings</span><span class="up">−${money(b.productDiscount)}</span></div><div class="line"><span>Coupon discount</span><span class="up">−${money(b.coupon)}</span></div><div class="line"><span>CGST + SGST</span><span>${money(b.cgst+b.sgst)}</span></div><div class="line"><span>Delivery</span><span>${b.delivery?money(b.delivery):'FREE'}</span></div><div class="line total"><span>Grand total</span><span>${money(b.total)}</span></div><p class="up">You saved ${money(b.productDiscount+b.coupon)}</p><button class="btn" style="width:100%" onclick="go('checkout')">Proceed to checkout</button></aside></div>`}</main><div class="toast hidden"></div>`}
function details(id){let p=products.find(x=>x.id===Number(id));if(!validProduct(p))return go('shop');return `${nav()}<main class="wrap"><button class="link" onclick="go('shop')">← Back to shop</button><div class="cart-layout" style="margin-top:16px"><section class="panel"><div class="product-img" style="height:360px;font-size:145px">${p.icon}</div><div class="muted" style="margin-top:14px">Product gallery · 2-year limited warranty · Ships within 24 hours</div></section><section class="panel"><div class="brand">${p.b} · SKU ELC-${String(p.id).padStart(3,'0')}</div><h1>${p.n}</h1><div class="rating">★ ${p.r} · ${p.reviewCount} verified reviews</div><div class="price">${money(p.p)} <span class="old">${money(p.old)}</span> <span class="up">${p.discount}% off</span></div><p class="stock">${p.stock?`${p.stock} units available`:'Currently unavailable'}</p><p class="muted">${p.description}</p><div class="hero-actions"><button class="btn" onclick="add(${p.id});go('cart')" ${p.stock?'':'disabled'}>Buy Now</button><button class="btn secondary" onclick="add(${p.id})">Add to Cart</button><button class="btn secondary" onclick="wish(${p.id})">♡ Wishlist</button></div><hr><b>Delivery & billing</b><p class="muted">GST 18% · HSN/SAC ${p.hsn} · Free delivery over ₹999</p></section></div><section class="section panel"><div class="eyebrow">Smart Recommendations</div><h2>Frequently bought together</h2><div class="grid">${products.filter(x=>x.c===p.c&&x.id!==p.id).slice(0,4).map(productCard).join('')}</div></section></main><div class="toast hidden"></div>`}
function wishlist(){if(!state.user)return login();let items=products.filter(p=>state.wish.includes(p.id));return `${nav()}<main class="wrap"><div class="section-head"><h2>Your wishlist</h2></div>${items.length?`<div class="grid">${items.map(productCard).join('')}</div>`:`<div class="panel empty"><h2>Save products you love.</h2><p class="muted">Your wishlist will be right here when inspiration strikes.</p><button class="btn" onclick="go('shop')">Explore Products</button></div>`}</main><div class="toast hidden"></div>`}
function login(){return `${nav()}<main class="wrap"><div class="panel auth"><div class="eyebrow">Secure demo access</div><h2>Welcome to BillCart</h2><p class="muted">Sign in to save your cart, place orders, and manage billing.</p><label>Email<input id="email" type="email" placeholder="Email address" value="customer@billcart.com"></label><label>Password<input id="password" type="password" placeholder="Password" value="demo123"></label><label class="muted"><input id="remember" type="checkbox" checked> Remember me</label><p><button class="link" onclick="toast('Password reset link prepared for this demo account.')">Forgot password?</button></p><button class="btn" style="width:100%" onclick="signIn()">Login</button><p style="text-align:center"><button class="link" onclick="registerDemo()">New here? Register</button></p><div class="demo"><b>Demo accounts</b><br>Customer: customer@billcart.com<br>Admin: admin@billcart.com<br><small>Use any password in this local demonstration.</small></div></div></main><div class="toast hidden"></div>`}
function myAccount(){if(!state.user)return login();let profile=state.profiles[state.user.id]||{name:state.user.name,email:state.user.email},addresses=state.addresses||[];return `${nav()}<main class="wrap"><div class="section-head"><div><div class="eyebrow">My Account</div><h2>Profile & delivery addresses</h2></div><button class="btn secondary" onclick="go('dashboard')">Dashboard</button></div><section class="panel"><form onsubmit="event.preventDefault();saveProfile()"><div class="form-grid"><label>Name<input id="profileName" value="${profile.name||''}" required></label><label>Email<input value="${profile.email||state.user.email}" disabled></label><label>Phone<input id="profilePhone" value="${profile.phone||''}" pattern="[0-9]{10}"></label></div><button class="btn">Save profile</button></form></section><section class="panel" style="margin-top:18px"><h3>Saved addresses</h3>${addresses.map((x,i)=>`<div class="cart-item"><div style="flex:1">${x.name} · ${x.phone}<br>${x.address}, ${x.city}, ${x.state} ${x.pincode}</div><button class="link" onclick="deleteAddress(${i})">Remove</button></div>`).join('')||'<p class="muted">No saved addresses yet.</p>'}<h3>Add address</h3><div class="form-grid"><input id="addrName" placeholder="Full name"><input id="addrPhone" placeholder="Phone" inputmode="numeric"><input id="addrLine" placeholder="Street address"><input id="addrCity" placeholder="City"><input id="addrState" placeholder="State"><input id="addrPin" placeholder="Six digit pincode"></div><button class="btn" onclick="addAddress()">Save address</button></section></main><div class="toast hidden"></div>`};function saveProfile(){let name=document.querySelector('#profileName').value.trim(),phone=document.querySelector('#profilePhone').value.trim();if(phone&&!/^\d{10}$/.test(phone))return toast('Enter a valid 10 digit phone number.');state.user.name=name;state.profiles[state.user.id]={...(state.profiles[state.user.id]||{}),name,email:state.user.email,phone};save();go('account')}function addAddress(){let ids=['addrName','addrPhone','addrLine','addrCity','addrState','addrPin'],v=Object.fromEntries(ids.map(x=>[x,document.querySelector('#'+x).value.trim()]));if(Object.values(v).some(x=>!x))return toast('Complete all address fields.');if(!/^\d{10}$/.test(v.addrPhone)||!/^\d{6}$/.test(v.addrPin))return toast('Check the 10 digit phone and six digit pincode.');state.addresses.push({name:v.addrName,phone:v.addrPhone,address:v.addrLine,city:v.addrCity,state:v.addrState,pincode:v.addrPin});save();go('account')}function deleteAddress(i){state.addresses.splice(i,1);save();go('account')}function trackOrder(id){let o=state.orders.find(x=>(x.orderId||x.id)===id&&x.userId===state.user?.id);if(!o)return go('orders');return `${nav()}<main class="wrap"><section class="panel"><div class="eyebrow">Order tracking</div><h2>${o.orderId}</h2><p>Current status: <span class="status">${o.orderStatus}</span></p><p class="muted">Placed ${o.createdAt}. Demo tracking updates when the order is fulfilled by the store.</p><button class="btn secondary" onclick="go('orders')">Back to orders</button></section></main><div class="toast hidden"></div>`};function cancelOrder(id){let o=state.orders.find(x=>(x.orderId||x.id)===id&&x.userId===state.user?.id);if(!o||!['Confirmed','Processing'].includes(o.orderStatus))return toast('This order can no longer be cancelled.');o.orderStatus='Cancelled';o.items.forEach(i=>{let p=products.find(p=>p.id===i.id);if(p)p.stock+=i.q});save();go('orders')}function requestReturn(id){let o=state.orders.find(x=>(x.orderId||x.id)===id&&x.userId===state.user?.id);if(!o||o.orderStatus!=='Delivered')return toast('Returns are available after delivery.');o.orderStatus='Return requested';save();go('orders')}
function dashboard(){if(!state.user)return login();let mine=state.orders.filter(o=>o.userId===state.user.id||o.customer===state.user.name),spent=mine.reduce((a,o)=>a+Number(o.grandTotal||o.bill?.total||0),0);return `${nav()}<main class="wrap"><div class="section-head"><div><div class="eyebrow">Customer dashboard</div><h2>Welcome back, ${state.user.name}</h2><p class="muted">Your shopping and billing overview.</p></div><button class="btn" onclick="go('shop')">Continue Shopping</button></div><div class="metrics"><div class="metric"><span class="muted">Total orders</span><b>${mine.length}</b></div><div class="metric"><span class="muted">Wishlist items</span><b>${state.wish.length}</b></div><div class="metric"><span class="muted">Cart items</span><b>${state.cart.reduce((a,x)=>a+x.q,0)}</b></div><div class="metric"><span class="muted">Total spending</span><b>${money(spent)}</b></div></div><section class="panel" style="margin-top:18px"><div class="section-head"><h3>Recent orders</h3><button class="link" onclick="go('orders')">View orders →</button></div>${mine.length?`<table class="table"><thead><tr><th>Order ID</th><th>Date</th><th>Total</th><th>Payment</th><th>Status</th></tr></thead><tbody>${mine.slice(0,5).map(o=>`<tr><td>${o.orderId||o.id}</td><td>${o.createdAt||o.date}</td><td>${money(o.grandTotal||o.bill?.total)}</td><td>${o.paymentMethod}</td><td><span class="status">${o.orderStatus}</span></td></tr>`).join('')}</tbody></table>`:`<p class="muted">No orders yet. Your completed purchases will appear here.</p>`}</section><section class="hero-actions"><button class="btn secondary" onclick="go('orders')">View Orders</button><button class="btn secondary" onclick="go('wishlist')">View Wishlist</button><button class="btn secondary" onclick="toast('Profile editing is ready for your saved account.')">View Profile</button></section></main><div class="toast hidden"></div>`}
function checkout(){if(!state.user)return go('login');let b=bill();if(!b.sub)return go('cart');let selected=state.checkout?.paymentMethod||'UPI';return `${nav()}<main class="wrap checkout"><div class="steps"><b>✓ Cart</b><b>→ Address</b><span>○ Payment</span><span>○ Confirmation</span></div><div class="cart-layout"><section class="panel"><div class="eyebrow">Delivery address</div><h2>Where should we deliver?</h2><div class="form-grid"><input id="full" placeholder="Full name" value="${state.user.name}"><input id="phone" placeholder="Phone" value="9876543210"><input id="address" placeholder="Address" value="42, Lake View Road"><input id="city" placeholder="City" value="Bengaluru"><input id="region" placeholder="State" value="Karnataka"><input id="pin" placeholder="Pincode" value="560001"></div><h3>Payment method</h3><label><input type="radio" name="paymentMethod" value="UPI" ${selected==='UPI'?'checked':''} onchange="setPayment(this.value)"> UPI (demo payment)</label><br><label><input type="radio" name="paymentMethod" value="Card" ${selected==='Card'?'checked':''} onchange="setPayment(this.value)"> Credit / Debit Card</label><br><label><input type="radio" name="paymentMethod" value="Cash on Delivery" ${selected==='Cash on Delivery'?'checked':''} onchange="setPayment(this.value)"> Cash on Delivery</label><p class="muted">Card information is never collected in this demonstration. Selected: <b id="selectedPayment">${selected}</b></p><label>Demo payment result<select id="demoPayment"><option value="success">Successful</option><option value="failure">Failed</option><option value="cancel">Cancelled by customer</option></select></label><button class="btn" onclick="placeOrder()">Place order · ${money(b.total)}</button></section><aside class="panel summary"><b>Order summary</b><div class="line"><span>Items</span><span>${state.cart.reduce((a,x)=>a+x.q,0)}</span></div><div class="line"><span>GST (CGST + SGST)</span><span>${money(b.cgst+b.sgst)}</span></div><div class="line total"><span>Amount payable</span><span>${money(b.total)}</span></div><p class="muted">Your invoice will include GSTIN, HSN/SAC, QR verification, and a price snapshot.</p></aside></div></main><div class="toast hidden"></div>`}
function orders(){if(!state.user)return login();let orders=(state.orders||[]).filter(o=>state.user?.role==='admin'||o.userId===state.user?.id);return `${nav()}<main class="wrap"><div class="section-head"><div><div class="eyebrow">Purchase history</div><h2>My orders</h2></div></div>${orders.length?`<section class="panel"><table class="table"><thead><tr><th>Order ID</th><th>Date</th><th>Items</th><th>Total</th><th>Payment Method</th><th>Payment Status</th><th>Order Status</th><th></th></tr></thead><tbody>${orders.map(o=>`<tr><td><b>${o.orderId||o.id}</b></td><td>${o.createdAt||o.date}</td><td>${o.items.length} item(s)</td><td>${money(o.grandTotal||o.bill?.total||0)}</td><td>${o.paymentMethod}</td><td><span class="status">${o.paymentStatus}</span></td><td><span class="status">${o.orderStatus}</span></td><td><button class="link" onclick="invoice('${o.orderId||o.id}')">Invoice</button> <button class="link" onclick="buyAgain('${o.orderId||o.id}')">Buy again</button> <button class="link" onclick="go('tracking','${o.orderId||o.id}')">Track</button> ${['Confirmed','Processing'].includes(o.orderStatus)?`<button class="link" onclick="cancelOrder('${o.orderId||o.id}')">Cancel</button>`:''} ${o.orderStatus==='Delivered'?`<button class="link" onclick="requestReturn('${o.orderId||o.id}')">Return</button>`:''}</td></tr>`).join('')}</tbody></table></section>`:`<div class="panel empty"><h2>You haven't placed any orders yet.</h2><button class="btn" onclick="go('shop')">Start Shopping</button></div>`}</main><div class="toast hidden"></div>`}
function invoice(id){let o=(state.orders||[]).find(x=>(x.orderId||x.id)===id&&(state.user?.role==='admin'||x.userId===state.user?.id));if(!o)return go('orders');let b=o.bill||{sub:o.subtotal||0,coupon:o.couponDiscount||0,taxable:o.taxableAmount||0,cgst:(o.gst||0)/2,sgst:(o.gst||0)/2,delivery:o.deliveryCharge||0,total:o.grandTotal||0};document.querySelector('#app').innerHTML=`${nav()}<main class="wrap"><div class="hero-actions" style="justify-content:flex-end"><button class="btn secondary" onclick="window.print()">Print invoice</button><button class="btn" onclick="window.print()">Download PDF</button></div><article class="invoice"><div class="invoice-header"><div><h1 style="margin:0"><span style="color:#3159e8">✓</span> BillCart</h1><b>E-Commerce Billing System</b><p>BillCart Retail Pvt. Ltd.<br>21 Market Street, Bengaluru · +91 80 4000 2026<br>GSTIN: 29AACCB1234M1ZX</p></div><div style="text-align:right"><h2>Tax Invoice</h2><b>Invoice: ${o.invoiceNumber||'INV-2026-'+id.slice(-4)}</b><p>Order: ${o.orderId||o.id}<br>${o.createdAt||o.date}</p><div class="qr" style="margin-left:auto"></div><small>Scan to verify invoice</small></div></div><p><b>Bill to:</b> ${o.customer||state.user?.name||'Customer'}<br>${o.deliveryAddress?.address||'42, Lake View Road'}, ${o.deliveryAddress?.city||'Bengaluru'}<br>Phone: ${o.deliveryAddress?.phone||'9876543210'}</p><table><thead><tr><th>Product / HSN</th><th>Qty</th><th>Unit price</th><th>Discount</th><th>Tax</th><th>Total</th></tr></thead><tbody>${o.items.map(x=>{let p=products.find(z=>z.id===x.id);let line=Number(x.price||p?.p||0)*x.q;return `<tr><td>${x.name||p?.n||'Product'}<br><small>HSN/SAC ${p?.hsn||'9988'}</small></td><td>${x.q}</td><td>${money(x.price||p?.p||0)}</td><td>${money((p?.old-p?.p||0)*x.q)}</td><td>${money(line*.18)}</td><td>${money(line*1.18)}</td></tr>`}).join('')}</tbody></table><div class="totals"><p>Subtotal <span style="float:right">${money(b.sub)}</span></p><p>Coupon discount <span style="float:right">−${money(b.coupon)}</span></p><p>Taxable amount <span style="float:right">${money(b.taxable)}</span></p><p>CGST (9%) <span style="float:right">${money(b.cgst)}</span></p><p>SGST (9%) <span style="float:right">${money(b.sgst)}</span></p><p>Delivery <span style="float:right">${money(b.delivery)}</span></p><h2>Grand Total <span style="float:right">${money(b.total)}</span></h2></div><hr><p><b>Payment Method:</b> ${o.paymentMethod} · <b>Payment Status:</b> <span class="status">${o.paymentStatus}</span> · Ref ${(o.orderId||o.id)}-PAY</p><p style="text-align:center;color:#687086;margin-top:35px">Thank you for shopping with BillCart.</p></article></main>`}
function admin(){if(state.user?.role!=='admin')return login();if(state.adminSection&&state.adminSection!=='Dashboard')return adminWorkspace(state.adminSection);let revenue=(state.orders||[]).reduce((a,o)=>a+Number(o.grandTotal||o.bill?.total||0),0);return `${nav()}<div class="admin"><aside class="side"><b style="padding:10px">ADMIN CONSOLE</b>${['Dashboard','Products','Orders','Inventory','Customers','Coupons','Invoices','Reports','Settings'].map((x,i)=>`<button class="${i===0?'active':''}" onclick="adminPanel('${x}')">${x}</button>`).join('')}</aside><main class="admin-content"><div class="section-head"><div><div class="eyebrow">Live business overview</div><h2>Good morning, Admin</h2></div><button class="btn secondary" onclick="exportCSV()">Export report</button></div><div class="metrics"><div class="metric"><span class="muted">Total sales</span><b>${money(revenue)}</b><span class="up">↗ 12.4% vs last month</span></div><div class="metric"><span class="muted">Total orders</span><b>${state.orders.length}</b><span class="muted">Recorded orders</span></div><div class="metric"><span class="muted">Total customers</span><b>${Object.keys(state.users).length}</b><span class="muted">Local demo accounts</span></div><div class="metric"><span class="muted">Total products</span><b>${products.length}</b><span style="color:#d77a00">${products.filter(p=>p.stock<8).length} low stock</span></div></div><div class="charts"><section class="panel"><h3>Sales overview</h3><div class="chart">${[45,67,39,78,62,91,74,97,83,68,89,100].map((n,i)=>`<div class="bar" style="height:${n}%" title="Month ${i+1}"></div>`).join('')}</div></section><section class="panel"><h3>Low-stock products</h3>${products.filter(p=>p.stock<8).map(p=>`<div class="cart-item"><div class="fakeimg">${p.icon}</div><div><b>${p.n}</b><br><span class="muted">${p.stock?p.stock+' units remaining':'Out of stock'}</span></div></div>`).join('')}</section></div><section class="panel" style="margin-top:16px"><h3>Recent orders</h3><table class="table"><thead><tr><th>Order ID</th><th>Customer</th><th>Amount</th><th>Payment Method</th><th>Payment Status</th><th>Order Status</th></tr></thead><tbody>${(state.orders||[]).map(o=>`<tr><td>${o.orderId||o.id}</td><td>${o.customer}</td><td>${money(o.grandTotal||o.bill?.total||0)}</td><td>${o.paymentMethod}</td><td><span class="status">${o.paymentStatus}</span></td><td><span class="status">${o.orderStatus}</span></td></tr>`).join('')||'<tr><td colspan="6" class="muted">New customer orders will appear here.</td></tr>'}</tbody></table></section></main></div><div class="toast hidden"></div>`}
function adminWorkspace(section){if(state.user?.role!=='admin')return login();let body='';if(section==='Products'||section==='Inventory')body=`<h2>${section} management</h2><div class="table-scroll"><table class="table"><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Actions</th></tr></thead><tbody>${products.map(p=>`<tr><td>${p.n}</td><td>${p.c}</td><td><input id="price-${p.id}" type="number" min="1" value="${p.p}" style="width:100px"></td><td><input id="stock-${p.id}" type="number" min="0" value="${p.stock}" style="width:85px"></td><td><button class="link" onclick="updateProduct(${p.id})">Save</button></td></tr>`).join('')}</tbody></table></div><h3>Add product</h3><div class="form-grid"><input id="newName" placeholder="Product name"><select id="newCategory">${categories.map(c=>`<option>${c[0]}</option>`).join('')}</select><input id="newBrand" placeholder="Brand"><input id="newPrice" type="number" placeholder="Price"><input id="newStock" type="number" placeholder="Stock"><input id="newIcon" placeholder="Emoji"></div><button class="btn" onclick="createProduct()">Add product</button>`;else if(section==='Orders')body=`<h2>Order management</h2><table class="table"><tr><th>Order</th><th>Customer</th><th>Status</th><th>Update status</th></tr>${state.orders.map(o=>`<tr><td>${o.orderId}</td><td>${o.customer}</td><td>${o.orderStatus}</td><td><select onchange="setOrderStatus(' ${o.orderId}',this.value)"><option>${o.orderStatus}</option><option>Processing</option><option>Shipped</option><option>Delivered</option><option>Cancelled</option></select></td></tr>`).join('')}</table>`;else if(section==='Customers')body=`<h2>Customers</h2><table class="table"><tr><th>Name</th><th>Email</th><th>Orders</th></tr>${Object.values(state.users).map(u=>`<tr><td>${u.profile?.name||'Customer'}</td><td>${u.profile?.email||''}</td><td>${state.orders.filter(o=>o.userId&&o.userId===Object.keys(state.users).find(k=>state.users[k]===u)).length}</td></tr>`).join('')}</table>`;else if(section==='Coupons')body=`<h2>Coupons</h2><p class="muted">Active demo codes: WELCOME10, SAVE20 (minimum ₹2,000), BILL50 (minimum ₹1,000), FREESHIP.</p><div class="form-grid"><input id="couponCode" placeholder="Code"><select id="couponType"><option value="percent">Percent</option><option value="fixed">Fixed ₹</option><option value="shipping">Free shipping</option></select><input id="couponValue" type="number" placeholder="Value"></div><button class="btn" onclick="createCoupon()">Add coupon</button><pre>${JSON.stringify(state.coupons,null,2)}</pre>`;else body=`<h2>${section}</h2><button class="btn" onclick="exportCSV()">Export inventory CSV</button>`;return `${nav()}<main class="wrap"><button class="link" onclick="state.adminSection='Dashboard';go('admin')">← Dashboard</button><section class="panel" style="margin-top:14px">${body}</section></main><div class="toast hidden"></div>`}function updateStock(id){let value=Number(document.querySelector('#stock-'+id).value);if(!Number.isInteger(value)||value<0)return toast('Stock must be a non-negative whole number.');products.find(p=>p.id===id).stock=value;save();toast('Inventory updated.')}function updateProduct(id){let p=products.find(x=>x.id===id),price=Number(document.querySelector('#price-'+id).value);if(!Number.isFinite(price)||price<=0)return toast('Price must be greater than zero.');p.p=p.price=price;if(p.old<price)p.old=p.originalPrice=Math.round(price*1.2);p.discount=Math.round((1-price/p.old)*100);updateStock(id);}function createProduct(){let n=document.querySelector('#newName').value.trim(),c=document.querySelector('#newCategory').value,b=document.querySelector('#newBrand').value.trim(),p=Number(document.querySelector('#newPrice').value),stock=Number(document.querySelector('#newStock').value),icon=document.querySelector('#newIcon').value||'🛍️';if(!n||!b||p<=0||stock<0)return toast('Enter a name, brand, positive price, and valid stock.');if(products.some(x=>x.n.toLowerCase()===n.toLowerCase()))return toast('A product with that name already exists.');let id=Math.max(...products.map(x=>x.id))+1;products.push({id,n,b,c,p,old:Math.round(p*1.2),stock,icon,r:4.2,hsn:'9988',name:n,category:c,price:p,originalPrice:Math.round(p*1.2),image:productFallback({id,n,name:n,icon}),description:n+' by '+b,brand:b,rating:4.2,reviewCount:0,discount:17});toast('Product added to this session catalogue.')}function setOrderStatus(id,status){id=id.trim();let o=state.orders.find(x=>x.orderId===id);if(o){o.orderStatus=status;save();toast('Order status updated.')}}function createCoupon(){let code=document.querySelector('#couponCode').value.trim().toUpperCase(),type=document.querySelector('#couponType').value,value=Number(document.querySelector('#couponValue').value);if(!code||value<0)return toast('Enter a code and non-negative value.');state.coupons[code]={type,value};save();go('admin','Coupons')}
function assistant(){return `<div class="assistant"><b>✦ Smart Shopping Assistant</b><div class="answer" id="answer">Ask about products under a budget or best rated picks.</div><input placeholder="e.g. products under ₹2000" onkeydown="if(event.key==='Enter')ask(this.value)"></div>`}function footer(){return `<footer class="wrap muted" style="padding:28px 22px;border-top:1px solid var(--line)"><b>BillCart</b> · Shop smart. Bill simple. <span style="float:right">© 2026 BillCart. All rights reserved.</span></footer>`}
function go(page,arg,replace=false){if(page==='invoice'){if(!replace)history.pushState({route:'invoice/'+encodeURIComponent(arg||'')},'',location.pathname+'#/invoice/'+encodeURIComponent(arg||''));return invoice(arg)}let f={home,shop,cart,wishlist,login,register:registerDemo,dashboard,account:myAccount,checkout,orders,admin,invoice,success,tracking:trackOrder};let route=page+(arg?'/'+encodeURIComponent(arg):'');if(!replace)history.pushState({route},'',location.pathname+'#/'+route);document.querySelector('#app').innerHTML=(f[page]||home)(arg);window.scrollTo(0,0)}
function loadRoute(){let parts=(location.hash.replace(/^#\/?/,'')||'home').split('/').map(decodeURIComponent),page=parts[0];if(page==='product')return details(Number(parts[1]));if(page==='invoice')return invoice(parts[1]);if(page==='orders'&&parts[1])return invoice(parts[1]);let f={home,shop,cart,wishlist,login,register:registerDemo,dashboard,account:myAccount,checkout,orders,admin,success,tracking:trackOrder};document.querySelector('#app').innerHTML=(f[page]||home)(parts[1])}
function add(id){if(!state.user){toast('Sign in to use your personal cart.');return go('login')}let p=products.find(x=>x.id===Number(id)),x=state.cart.find(x=>x.id===Number(id));if(!validProduct(p))return toast('This product is unavailable.');if(!p.stock)return toast('This product is currently unavailable.');if(x){if(x.q>=p.stock)return toast('Only '+p.stock+' units available.');x.q++}else state.cart.push({id:p.id,q:1});save();toast('✓ Added to cart');loadRoute()}
function wish(id){if(!state.user){toast('Sign in to save your wishlist.');return go('login')}state.wish.includes(id)?state.wish=state.wish.filter(x=>x!==id):state.wish.push(id);save();toast('✓ Wishlist updated');loadRoute()}
function qty(id,d){let x=state.cart.find(x=>x.id===id),p=products.find(p=>p.id===id);if(x.q+d<1)return remove(id);if(x.q+d>p.stock)return toast('Maximum stock reached');x.q+=d;save();go('cart')}function remove(id){state.cart=state.cart.filter(x=>x.id!==id);save();go('cart')}
function applyCoupon(){let code=document.querySelector('#coupon').value.trim().toUpperCase(),b=bill(),coupon=state.coupons[code];if(!coupon)return toast('Coupon not found or expired.');if(coupon.min&&b.sub<coupon.min)return toast(code+' needs a '+money(coupon.min)+' cart.');state.coupon=code;save();toast('✓ Coupon applied');go('cart')}
function signIn(){let email=(document.querySelector('#email').value||'').trim().toLowerCase(),password=document.querySelector('#password').value;if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return toast('Enter a valid email address.');if(!password)return toast('Enter your password.');let role=email==='admin@billcart.com'?'admin':'customer',id='usr-'+email.replace(/[^a-z0-9]/g,''),saved=state.users[id]||{};if(!saved.password&&!['customer@billcart.com','admin@billcart.com'].includes(email))return toast('No account found for this email. Please register first.');if(saved.password&&saved.password!==password)return toast('Incorrect password.');let user={id,name:role==='admin'?'Aarav Mehta':saved.profile?.name||(email==='customer@billcart.com'?'Priya Sharma':email.split('@')[0]),email,role};switchUser(user);state.cart.forEach(x=>x.q=Math.min(x.q,products.find(p=>p.id===x.id)?.stock||1));state.checkout=state.checkout||{paymentMethod:'UPI'};save();toast('Signed in successfully');go(role==='admin'?'admin':'dashboard')}
function logout(){state.user=null;state.checkout={paymentMethod:'UPI'};save();go('home');setTimeout(()=>toast('You have been logged out.'),0)}
function registerDemo(){document.querySelector('#app').innerHTML=`${nav()}<main class="wrap"><form class="panel auth" onsubmit="event.preventDefault();registerAccount()"><div class="eyebrow">Create your account</div><h2>Join BillCart</h2><label>Full name<input id="regName" required minlength="2"></label><label>Email<input id="regEmail" required type="email"></label><label>Password<input id="regPassword" required type="password" minlength="6"></label><label>Phone<input id="regPhone" inputmode="numeric" pattern="[0-9]{10}"></label><button class="btn">Create account</button><p><button type="button" class="link" onclick="go('login')">Already registered? Login</button></p></form></main><div class="toast hidden"></div>`}function registerAccount(){let name=document.querySelector('#regName').value.trim(),email=document.querySelector('#regEmail').value.trim().toLowerCase(),password=document.querySelector('#regPassword').value,phone=document.querySelector('#regPhone').value.trim(),id='usr-'+email.replace(/[^a-z0-9]/g,'');if(!name||password.length<6||!email.includes('@'))return toast('Enter a name, valid email, and password of at least 6 characters.');if(state.users[id])return toast('An account with this email already exists.');let user={id,name,email,role:'customer'};state.users[id]={password,cart:[],wish:[],addresses:[],profile:{name,email,phone}};state.profiles[id]={name,email,phone};switchUser(user);save();go('dashboard')}
function setPayment(paymentMethod){state.checkout={...(state.checkout||{}),paymentMethod};save();let label=document.querySelector('#selectedPayment');if(label)label.textContent=paymentMethod}
function placeOrder(){if(!state.user)return go('login');let required=['full','phone','address','city','region','pin'];let values=Object.fromEntries(required.map(k=>[k,(document.querySelector('#'+k)?.value||'').trim()]));if(required.some(k=>!values[k]))return toast('Please complete the delivery address.');if(!/^\d{6}$/.test(values.pin))return toast('Enter a valid six-digit pincode.');if(!state.cart.length)return go('cart');let invalid=state.cart.find(x=>{let p=products.find(p=>p.id===x.id);return !validProduct(p)||x.q>p.stock});if(invalid)return toast('One or more items no longer have sufficient stock.');let b=bill(),paymentMethod=state.checkout?.paymentMethod||document.querySelector('input[name="paymentMethod"]:checked')?.value,demoResult=document.querySelector('#demoPayment')?.value||'success';if(demoResult==='failure'){toast('Demo payment failed. Your cart is unchanged; retry checkout when ready.');return}if(demoResult==='cancel'){toast('Payment cancelled. Your cart is unchanged.');go('cart');return}if(!['UPI','Card','Cash on Delivery'].includes(paymentMethod))return toast('Select a valid payment method.');let orderId='ORD-2026-'+String(10025+state.orders.length),createdAt=new Date().toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}),items=state.cart.map(x=>{let p=products.find(p=>p.id===x.id);return {id:p.id,name:p.n,image:p.icon,price:p.p,originalPrice:p.old,discount:p.discount,quantity:x.q,q:x.q,category:p.c,availableStock:p.stock}});let order={orderId,id:orderId,invoiceNumber:'INV-2026-'+String(10025+state.orders.length),userId:state.user.id,customer:state.user.name,items,subtotal:b.sub,productDiscount:b.productDiscount,couponDiscount:b.coupon,taxableAmount:b.taxable,gst:b.cgst+b.sgst,deliveryCharge:b.delivery,grandTotal:b.total,paymentMethod,paymentStatus:paymentMethod==='Cash on Delivery'?'Pending':'Paid',deliveryAddress:{name:values.full,phone:values.phone,address:values.address,city:values.city,state:values.region,pincode:values.pin},orderStatus:'Confirmed',createdAt,date:createdAt,bill:b};state.orders.unshift(order);state.cart.forEach(x=>products.find(p=>p.id===x.id).stock-=x.q);state.cart=[];state.coupon='';state.checkout={paymentMethod:'UPI'};save();toast('✓ Order placed successfully');go('success',orderId)}
function success(id){let o=state.orders.find(x=>(x.orderId||x.id)===id&&(state.user?.role==='admin'||x.userId===state.user?.id));if(!o)return go('orders');return `${nav()}<main class="wrap"><div class="panel empty"><div style="font-size:44px">🎉</div><div class="eyebrow">Order confirmation</div><h1>Order Placed Successfully</h1><p class="muted">Your order is confirmed and a GST invoice is ready.</p><div class="panel" style="max-width:520px;margin:22px auto;text-align:left"><div class="line"><span>Order ID</span><b>${o.orderId}</b></div><div class="line"><span>Order Date</span><b>${o.createdAt}</b></div><div class="line"><span>Payment Method</span><b>${o.paymentMethod}</b></div><div class="line"><span>Payment Status</span><b>${o.paymentStatus}</b></div><div class="line"><span>Delivery Address</span><b>${o.deliveryAddress.address}, ${o.deliveryAddress.city}</b></div><div class="line total"><span>Total Amount</span><b>${money(o.grandTotal)}</b></div></div><button class="btn" onclick="invoice('${o.orderId}')">View Invoice</button> <button class="btn secondary" onclick="go('orders')">View Orders</button></div></main><div class="toast hidden"></div>`}
function buyAgain(id){let o=state.orders.find(x=>(x.orderId||x.id)===id&&x.userId===state.user?.id);if(!o)return toast('Order not found.');o.items.forEach(x=>{let p=products.find(z=>z.id===x.id);if(p.stock){let c=state.cart.find(z=>z.id===x.id);if(c)c.q=Math.min(c.q+x.q,p.stock);else state.cart.push({id:x.id,q:Math.min(x.q,p.stock)})}});save();toast('Available items added to cart');go('cart')}
function search(v){let query=String(v||'').trim();if((location.hash||'').includes('/shop')){shopFilters.query=query;renderShopGrid();return}if(!query){loadRoute();return}let found=products.filter(p=>`${p.n} ${p.b} ${p.c}`.toLowerCase().includes(query.toLowerCase()));let safe=query.replace(/[<>]/g,'');document.querySelector('#app').innerHTML=`${nav()}<main class="wrap"><div class="section-head"><h2>Search results for “${safe}”</h2><span class="muted">${found.length} products</span></div>${found.length?`<div class="grid">${found.map(productCard).join('')}</div>`:'<div class="panel empty">No products found.</div>'}</main><div class="toast hidden"></div>`;let input=document.querySelector('#search');if(input){input.value=query;input.focus();input.setSelectionRange(query.length,query.length)}}function filterPrice(v){shopFilters.max=Number(v);renderShopGrid()}function filterStock(v){shopFilters.stock=!!v;renderShopGrid()}function sortProducts(v){shopFilters.sort=v;renderShopGrid()}function ask(q){let m=q.match(/under\s*₹?\s*(\d+)/i);let a=m?products.filter(p=>p.p<=+m[1]).slice(0,3).map(p=>p.n).join(', '):[...products].sort((a,b)=>b.r-a.r).slice(0,3).map(p=>p.n).join(', ');document.querySelector('#answer').textContent=a?'Try: '+a:'No matches at that budget.'}function toggleTheme(){state.dark=!state.dark;save();document.body.classList.toggle('dark');loadRoute()}function exportCSV(){let csv='Product,SKU,Stock,Price\n'+products.map(p=>`${p.n},ELC-${p.id},${p.stock},${p.p}`).join('\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='billcart-inventory.csv';a.click();toast('CSV report exported')}function adminPanel(x){state.adminSection=x;save();go('admin')}
loadRoute();
